#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Scene art's go-live (issue #68): the reference birds exported from the pack builds, the deploy with the art
# buckets, queue and worker user, the worker's access key and settings written straight to comfybox (never to this
# Mac's disk or the repo), the worker copied there and its service installed, and a check that it polls.
#
#   infra/scripts/art-wizard.sh                  # from the start
#   WIZARD_FROM=3 infra/scripts/art-wizard.sh    # resume at stage 3 (e.g. after a deploy done by hand)
#   ART_BOX=matt@comfybox                        # the box (default)
#
# Run infra/scripts/accounts-wizard.sh and circles-wizard.sh first: this one reuses their deploy. The FLUX.3 ComfyUI
# must already run on the box (art/README.md, "comfybox").

run_wizard() {

TOTAL_STAGES=6
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq ssh rsync uv; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_DIR="$(cd "$INFRA_DIR/.." && pwd)"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
STACK_REGION="us-west-2"
BOX="${ART_BOX:-matt@comfybox}"
WORKER_USER="birdjournal-art-worker"
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"

AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

# begin "Name" starts the next stage, or skips it (returning 1) when it comes before WIZARD_FROM.
begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

stack_output() {
  aws cloudformation describe-stacks --region "$STACK_REGION" --stack-name BirdJournal \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text 2>/dev/null
}

banner "BirdJournal: scene art on comfybox"

if begin "Export the reference birds from the pack builds"; then
  say "Scene art paints each species' isolated reference bird, the one its pack art was painted from."
  say "They come from the pack builds' cache (packbuilder/cache/art/isolated) and the built packs in packs/."
  for pack_dir in "$REPO_DIR"/packs/*/; do
    id=$(basename "$pack_dir")
    [[ -f "$pack_dir/pack.sqlite" && -f "$REPO_DIR/packbuilder/packs/$id/art.lock.json" ]] || continue
    step "$id"
    (cd "$REPO_DIR/packbuilder" && uv run --quiet packbuilder art-references "packs/$id" --pack "$pack_dir" \
      --out "$REPO_DIR/build/art-references/$id") || warn "$id: export failed"
  done
  ls "$REPO_DIR"/build/art-references/*/references.json >/dev/null 2>&1 || {
    warn "No reference birds exported. Fetch or build a pack with art first (scripts/download-pack.sh), then resume."
    exit 1
  }
  note "A species missing from the cache gets no scene art (its card keeps pack art); rebuild its pack art to add it."
  pause
fi

if begin "Deploy the stack with the art pipeline"; then
  say "infra/scripts/deploy.sh runs the template tests, checks the shared bootstrap, and deploys the upload"
  say "bucket (a one-day lifecycle), the art CDN, the queue with its dead-letter queue, the worker token and"
  say "the $WORKER_USER IAM user, limited to the queue, reading uploads/ and writing art/."
  note "Account $AWS_ACCOUNT · profile $AWS_PROFILE · region $STACK_REGION"
  if confirm "Deploy BirdJournal now?"; then
    "$INFRA_DIR/scripts/deploy.sh"
  else
    SKIPPED+=("deploy: infra/scripts/deploy.sh, then WIZARD_FROM=3 infra/scripts/art-wizard.sh")
    finish; exit 0
  fi
  pause
fi

if begin "The worker's access key and settings, written to comfybox"; then
  say "The worker signs its SQS and S3 calls as $WORKER_USER. This makes it an access key and writes the"
  say "key, the stack's queue, buckets and API and the worker token to ~/birdjournal-art/artworker.env on"
  say "$BOX (mode 600). Nothing is saved on this Mac."
  queue=$(stack_output ArtQueueUrl); uploads=$(stack_output ArtUploadBucket); art=$(stack_output ArtBucket)
  api=$(stack_output ApiUrl); secret=$(stack_output ArtWorkerTokenSecret)
  [[ -n "$queue" && "$queue" != "None" ]] || { warn "No ArtQueueUrl output: deploy first (WIZARD_FROM=2)."; exit 1; }
  keys=$(aws iam list-access-keys --user-name "$WORKER_USER" --query 'length(AccessKeyMetadata)' --output text)
  make_key=y
  if (( keys >= 1 )); then
    warn "$WORKER_USER already has $keys access key(s). A new one leaves the old one working (IAM allows two)."
    note "Delete the old one once the box uses the new key: aws iam delete-access-key --user-name $WORKER_USER --access-key-id <id>"
    confirm "Make a new key and replace the box's settings?" || make_key=n
  fi
  if [[ "$make_key" == y ]]; then
    read -r key_id key_secret < <(aws iam create-access-key --user-name "$WORKER_USER" \
      --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)
    token=$(aws secretsmanager get-secret-value --region "$STACK_REGION" --secret-id "$secret" --query SecretString --output text)
    ssh "$BOX" 'mkdir -p ~/birdjournal-art && umask 077 && cat > ~/birdjournal-art/artworker.env' <<ENV
AWS_ACCESS_KEY_ID=$key_id
AWS_SECRET_ACCESS_KEY=$key_secret
AWS_REGION=$STACK_REGION
ART_QUEUE_URL=$queue
ART_UPLOAD_BUCKET=$uploads
ART_BUCKET=$art
ART_API_URL=$api
ART_WORKER_TOKEN=$token
COMFY_URL=http://127.0.0.1:8189
ART_REFERENCES=/home/matt/birdjournal-art/references
ART_FILTER_MODEL=/home/matt/birdjournal-art/models/nsfw_image_detection.onnx
ART_CACHE=/home/matt/birdjournal-art/cache
ENV
    unset key_secret token
    printf '  %s✓ wrote%s ~/birdjournal-art/artworker.env on %s (key %s)\n' "$GREEN" "$RESET" "$BOX" "$key_id"
  else
    SKIPPED+=("worker key: kept the box's existing settings")
  fi
  pause
fi

if begin "Copy the worker to comfybox"; then
  say "artworker/comfybox/deploy-to-comfybox.sh copies art/, packbuilder/ and artworker/ and the reference birds,"
  say "installs the worker's environment with uv and downloads the content filter (SHA-256 checked)."
  "$REPO_DIR/artworker/comfybox/deploy-to-comfybox.sh" "$BOX"
  pause
fi

if begin "Install and start the service"; then
  say "With sudo on the box: birdjournal-artworker.service, after comfyui-flux3.service, restarting on failure."
  ssh -t "$BOX" 'sudo sh ~/birdjournal-art/repo/artworker/comfybox/install-artworker-service.sh'
  pause
fi

if begin "Check that the worker polls"; then
  say "The service's log should say it is polling the queue, with its reference birds per pack."
  ssh "$BOX" 'journalctl -u birdjournal-artworker --no-pager -n 20' || true
  if ssh "$BOX" 'journalctl -u birdjournal-artworker --no-pager -n 50 | grep -q "art worker polling"'; then
    printf '  %s✓%s the worker is polling\n' "$GREEN" "$RESET"
  else
    warn "No 'art worker polling' line yet. Look with: ssh $BOX journalctl -fu birdjournal-artworker"
    SKIPPED+=("worker check: WIZARD_FROM=6 infra/scripts/art-wizard.sh")
  fi
  pause
fi

finish
note "on the glasses: sign in, add a bird with a photo, and watch the card go from 'Artwork is on its way'"
note "to the painting (journalctl -fu birdjournal-artworker on the box shows the job)."
printf '\n'
}

run_wizard "$@"; exit
